"""ORM models. Every table class subclasses `Base`.

Models are persistence details: repositories map them to and from domain objects, and they
never leave `infrastructure/`. `migrations/env.py` imports this module, so a model defined
in another module must be imported here for `make migration` to see it.
"""

from sqlalchemy import MetaData
from sqlalchemy.orm import DeclarativeBase

# Deterministic constraint names: Alembic can then drop or alter a constraint by name,
# and autogenerated migrations are the same on every machine.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)
